/* 학습 해설
 * 비계층 IRQ 데이터 검색: 부모 순회 없는 대체 구현
 * 계층 지원이 꺼진 빌드에서는 부모 사슬 검색을 설명한 앞 수업의 반복문이 존재하지 않습니다.
 * 이 대체 구현은 irq_get_irq_data(virq)로 첫 data 하나만 얻고 data가 있으면서 domain 포인터가 입력과 같으면 반환합니다. 아니면 NULL입니다. &&의 단락 평가 때문에 data가 NULL이면 data->domain을 읽지 않습니다. 부모를 따라가는 루프도 참조 획득이나 잠금 호출도 없습니다. 같은 함수의 첫 정의는 계층형 검색이고 이 수업의 원문 연결은 두 번째 정의를 사용합니다.
 * data=NULL, data.domain=A·입력 A, data.domain=A·입력 B 세 경우를 평가하세요. 이름 문자열이 같아도 다른 domain 주소이면 일치하지 않음을 적으세요.
 */
struct irq_data *irq_domain_get_irq_data(struct irq_domain *domain,
					 unsigned int virq)
{
	struct irq_data *irq_data = irq_get_irq_data(virq);

	return (irq_data && irq_data->domain == domain) ? irq_data : NULL;
}
EXPORT_SYMBOL_GPL(irq_domain_get_irq_data);

/**
 * irq_domain_set_info - Set the complete data for a @virq in @domain
 * @domain:		Interrupt domain to match
 * @virq:		IRQ number
 * @hwirq:		The hardware interrupt number
 * @chip:		The associated interrupt chip
 * @chip_data:		The associated interrupt chip data
 * @handler:		The interrupt flow handler
 * @handler_data:	The interrupt flow handler data
 * @handler_name:	The interrupt handler name
 */
void irq_domain_set_info(struct irq_domain *domain, unsigned int virq,
			 irq_hw_number_t hwirq, const struct irq_chip *chip,
			 void *chip_data, irq_flow_handler_t handler,
			 void *handler_data, const char *handler_name)
{
	irq_set_chip_and_handler_name(virq, chip, handler, handler_name);

/* 학습 해설
 * 비계층 IRQ 정보 설정: 쓰이지 않는 domain과 hwirq 인자
 * 공통 함수 서명이 같아도 설정별 구현이 모든 인자를 사용하는 것은 아니므로 호출 이름에서 동작을 추측하면 안 됩니다.
 * 비계층 구현은 irq_set_chip_and_handler_name으로 chip·flow handler·이름을 설정하고 irq_set_chip_data, irq_set_handler_data를 순서대로 호출합니다. 이 본문에서 domain과 hwirq 인자는 사용하지 않습니다. 계층형 구현처럼 domain별 data를 찾아 hwirq를 기록하는 호출도 없습니다. 반환형은 void이며 각 setter의 오류를 확인하는 조건이나 rollback이 없습니다. 이 함수만 호출하면 번호 매핑까지 새로 만들어진다고 설명하면 안 됩니다.
 * 함수 서명의 인자를 세 호출 중 어디로 전달하는지 화살표로 연결하고 domain·hwirq에는 이 본문에서 연결 화살표가 없음을 표시하세요.
 */
void irq_domain_set_info(struct irq_domain *domain, unsigned int virq,
			 irq_hw_number_t hwirq, const struct irq_chip *chip,
			 void *chip_data, irq_flow_handler_t handler,
			 void *handler_data, const char *handler_name)
{
	irq_set_chip_and_handler_name(virq, chip, handler, handler_name);
	irq_set_chip_data(virq, chip_data);
	irq_set_handler_data(virq, handler_data);
}

