#ifdef CONFIG_GENERIC_IRQ_DEBUGFS
#include "internals.h"

static struct dentry *domain_dir;

/* 학습 해설
 * IRQ domain 진단: 배열 크기·매핑 수·부모 출력 구분
 * 진단 화면의 size와 mapped를 같은 값으로 읽으면 빈 선형 슬롯과 실제 연결 수를 혼동할 수 있습니다.
 * name, revmap_size를 size, mapcount를 mapped, flags를 16진수로 출력합니다. irqdomain_flags 표의 10개 비트 설명을 irq_debug_show_bits에 넘기고 ops->debug_show가 있으면 irq_data 자리에는 NULL, 들여쓰기는 ind+1로 호출합니다. 계층 지원 빌드에서 부모가 있으면 부모 이름을 쓰고 ind+4로 재귀 출력합니다. 배열 크기가 0인 트리 domain에도 실제 매핑이 있을 수 있어 size=0을 IRQ 없음으로 보면 안 됩니다.
 * revmap_size=16,mapcount=3이면 16개 선형 슬롯과 현재 기록된 매핑 수 3을 구분하세요. 부모마다 들여쓰기가 4씩 깊어지는 출력 예를 그리세요.
 */
static void irq_domain_debug_show_one(struct seq_file *m, struct irq_domain *d, int ind)
{
	seq_printf(m, "%*sname:   %s\n", ind, "", d->name);
	seq_printf(m, "%*ssize:   %u\n", ind + 1, "", d->revmap_size);
	seq_printf(m, "%*smapped: %u\n", ind + 1, "", d->mapcount);
	seq_printf(m, "%*sflags:  0x%08x\n", ind +1 , "", d->flags);
	irq_debug_show_bits(m, ind, d->flags, irqdomain_flags, ARRAY_SIZE(irqdomain_flags));
	if (d->ops && d->ops->debug_show)
		d->ops->debug_show(m, d, NULL, ind + 1);
#ifdef	CONFIG_IRQ_DOMAIN_HIERARCHY
	if (!d->parent)
		return;
	seq_printf(m, "%*sparent: %s\n", ind + 1, "", d->parent->name);
	irq_domain_debug_show_one(m, d->parent, ind + 4);
#endif
}

static int irq_domain_debug_show(struct seq_file *m, void *p)
{
	struct irq_domain *d = m->private;

	/* Default domain? Might be NULL */
	if (!d) {
		if (!irq_default_domain)
			return 0;
		d = irq_default_domain;

/* 학습 해설
 * IRQ domain 진단 파일: 기본 domain을 읽을 때 선택하기
 * default라는 진단 파일은 생성 당시 특정 domain을 고정 저장하는 것과 현재 기본 domain을 찾아 보여 주는 것이 다릅니다.
 * m->private가 있으면 그 domain을 출력합니다. 없으면 irq_default_domain을 확인하고 그것도 없으면 내용 없이 성공 0입니다. 기본 domain이 있으면 그 값을 선택해 show_one(m,d,0)을 호출합니다. DEFINE_SHOW_ATTRIBUTE가 이 show 함수를 쓰는 파일 연산 연결을 만듭니다. default 파일은 private data를 NULL로 생성하므로 읽기 경로에서 기본 domain을 선택합니다. 이 본문에 domain 참조 카운터 증가나 잠금 획득은 없습니다.
 * 일반 파일의 private=A인 경우와 default 파일의 private=NULL·기본=B인 경우를 비교하세요. 기본값도 NULL이면 빈 출력과 오류 반환이 같은 뜻인지 적으세요.
 */
static int irq_domain_debug_show(struct seq_file *m, void *p)
{
	struct irq_domain *d = m->private;

	/* Default domain? Might be NULL */
	if (!d) {
		if (!irq_default_domain)
			return 0;
		d = irq_default_domain;
	}
	irq_domain_debug_show_one(m, d, 0);
	return 0;
}
DEFINE_SHOW_ATTRIBUTE(irq_domain_debug);

static void debugfs_add_domain_dir(struct irq_domain *d)
{
	if (!d->name || !domain_dir)
		return;
	debugfs_create_file(d->name, 0444, domain_dir, d,
			    &irq_domain_debug_fops);
}

static void debugfs_remove_domain_dir(struct irq_domain *d)
{
	debugfs_lookup_and_remove(d->name, domain_dir);

/* 학습 해설
 * IRQ debugfs 수명: 목록 등록·읽기 권한·삭제 연결
 * domain별 진단 파일이 언제 만들어지고 사라지는지 알아야 실제 자원과 진단 파일을 같은 객체로 혼동하지 않습니다.
 * init은 root 아래 domains 디렉터리를 만들고 default 파일을 0444 권한·NULL private로 생성합니다. irq_domain_mutex를 잡아 domain 목록을 순회하며 debugfs_add_domain_dir를 호출한 뒤 풉니다. add helper는 이름이나 domain_dir이 NULL이면 반환하고 그 외에는 domain 이름의 0444 파일을 만들며 private에 domain을 저장합니다. remove helper는 이름과 domain_dir로 lookup_and_remove를 호출합니다. 이 helper가 IRQ domain 객체 자체를 free하는 것은 아닙니다.
 * 기존 domain A·B가 있는 초기화에서 domains/default와 domains/A·B가 만들어지는 관계를 그리세요. 권한 0444가 쓰기 비트를 포함하지 않는다는 점을 적으세요.
 */
void __init irq_domain_debugfs_init(struct dentry *root)
{
	struct irq_domain *d;

	domain_dir = debugfs_create_dir("domains", root);

	debugfs_create_file("default", 0444, domain_dir, NULL,
			    &irq_domain_debug_fops);
	mutex_lock(&irq_domain_mutex);
	list_for_each_entry(d, &irq_domain_list, link)
		debugfs_add_domain_dir(d);
	mutex_unlock(&irq_domain_mutex);
}
#endif

/* 학습 해설
 * IRQ 진단 비활성 빌드: 빈 helper로 유지하는 공통 호출부
 * 진단 기능을 끈 빌드에서도 domain 생성·제거 코드는 같은 helper를 호출할 수 있도록 인터페이스를 유지할 필요가 있습니다.
 * CONFIG_GENERIC_IRQ_DEBUGFS가 켜지면 파일 앞부분은 add/remove 함수의 선언만 제공하고 뒤쪽 실제 정의가 컴파일됩니다. 꺼지면 debugfs_add_domain_dir와 debugfs_remove_domain_dir를 static inline 빈 본문으로 정의합니다. 이 빌드의 호출은 진단 파일 생성이나 삭제를 수행하지 않습니다. domain 생성·매핑 기능 전체를 끄는 것이 아니라 진단용 부수 작업을 생략하는 구조입니다. 함수가 void라 이 대체 경로에서 호출자에게 실패 코드를 돌려주지도 않습니다.
 * 설정 켜짐과 꺼짐에서 add helper의 실제 본문이 어디인지 표시하세요. 빈 helper를 호출한 뒤 domain 생성 본체는 계속 진행할 수 있는 이유를 설명하세요.
 */
static inline void debugfs_add_domain_dir(struct irq_domain *d) { }
static inline void debugfs_remove_domain_dir(struct irq_domain *d) { }
#endif

static const char *irqchip_fwnode_get_name(const struct fwnode_handle *fwnode)
{
	struct irqchip_fwid *fwid = container_of(fwnode, struct irqchip_fwid, fwnode);

	return fwid->name;
}

const struct fwnode_operations irqchip_fwnode_ops = {
	.get_name = irqchip_fwnode_get_name,
};
EXPORT_SYMBOL_GPL(irqchip_fwnode_ops);

/**
 * __irq_domain_alloc_fwnode - Allocate a fwnode_handle suitable for
 *                           identifying an irq domain
 * @type:	Type of irqchip_fwnode. See linux/irqdomain.h
 * @id:		Optional user provided id if name != NULL
 * @name:	Optional user provided domain name
 * @pa:		Optional user-provided physical address
 *
 * Allocate a struct irqchip_fwid, and return a pointer to the embedded
 * fwnode_handle (or NULL on failure).
 *
 * Note: The types IRQCHIP_FWNODE_NAMED and IRQCHIP_FWNODE_NAMED_ID are
 * solely to transport name information to irqdomain creation code. The
 * node is not stored. For other types the pointer is kept in the irq
 * domain struct.
 */

/* 학습 해설
 * IRQ 진단 삭제 helper: 이름으로 제거하고 객체 수명은 분리하기
 * domain의 진단 항목을 없애는 작업과 domain 메모리를 반납하는 작업은 대상과 호출 계약이 다릅니다.
 * 진단 활성 빌드의 debugfs_remove_domain_dir는 debugfs_lookup_and_remove(d->name,domain_dir)를 한 번 호출합니다. add helper에 있는 !d->name 또는 !domain_dir 검사도 이 삭제 wrapper에는 없습니다. create_file이 반환한 파일 포인터를 저장해 사용하는 구조가 아니라 부모 디렉터리와 현재 이름으로 찾아 제거하도록 위임합니다. 이 본문에는 kfree(d), 매핑 제거, IRQ 번호 반납이 없고 반환형도 void입니다. 이름 변경 경로에서는 어느 이름일 때 삭제하고 새 이름을 언제 등록하는지 순서를 함께 읽어야 합니다.
 * domain.name이 old일 때 삭제한 뒤 new로 바꾸어 등록하는 순서를 그리세요. 이름부터 new로 바꾼 뒤 old 파일을 찾으려 하면 검색에 어떤 이름을 전달하게 되는지 비교하세요.
 */
static void debugfs_remove_domain_dir(struct irq_domain *d)
{
	debugfs_lookup_and_remove(d->name, domain_dir);
}

void __init irq_domain_debugfs_init(struct dentry *root)
{
	struct irq_domain *d;

	domain_dir = debugfs_create_dir("domains", root);

	debugfs_create_file("default", 0444, domain_dir, NULL,
			    &irq_domain_debug_fops);
	mutex_lock(&irq_domain_mutex);
	list_for_each_entry(d, &irq_domain_list, link)
		debugfs_add_domain_dir(d);
	mutex_unlock(&irq_domain_mutex);
}
#endif

/* 학습 해설
 * 프로세스 생성의 CLONE_FS: 현재 디렉터리 상태를 공유할까 복사할까
 * 프로세스가 만들어질 때 모든 상태를 복사하면 메모리가 들고, 모두 공유하면 한쪽 변경이 다른 실행 흐름에 영향을 줍니다.
 * copy_fs는 CLONE_FS가 있으면 이미 자식에 연결된 fs_struct를 그대로 사용합니다. fs->lock을 잡아 in_exec이면 잠금을 풀고 -EAGAIN, 아니면 users를 증가시키고 성공합니다. 공유하지 않으면 copy_fs_struct 결과를 자식 fs에 넣고 NULL이면 -ENOMEM입니다. fs_struct는 현재 디렉터리·루트·umask 같은 파일시스템 문맥이며 열린 파일 descriptor 표 전체와 같은 객체가 아닙니다.
 * A와 B가 같은 fs_struct를 가리키는 그림과 서로 다른 fs_struct를 갖는 그림을 비교하세요. 이 helper에서 공유 경로는 새 객체 복사가 아니라 users 증가라는 점을 적으세요.
 */
static int copy_fs(unsigned long clone_flags, struct task_struct *tsk)
{
	struct fs_struct *fs = current->fs;
	if (clone_flags & CLONE_FS) {
		/* tsk->fs is already what we want */
		spin_lock(&fs->lock);
		/* "users" and "in_exec" locked for check_unsafe_exec() */
		if (fs->in_exec) {
			spin_unlock(&fs->lock);
			return -EAGAIN;
		}
		fs->users++;
		spin_unlock(&fs->lock);
		return 0;
	}
	tsk->fs = copy_fs_struct(fs);
	if (!tsk->fs)
		return -ENOMEM;
	return 0;
}

static int copy_files(unsigned long clone_flags, struct task_struct *tsk,
		      int no_files)
{
	struct files_struct *oldf, *newf;

/* 학습 해설
 * 메모리 부족 OOM 점수: RSS·swap·페이지 테이블과 정책 가중치
 * 메모리가 부족할 때 단순히 프로세스 수나 CPU 사용률로 희생 대상을 고르면 필요한 메모리를 충분히 회수하지 못할 수 있습니다.
 * oom_badness는 제외 대상이나 mm를 찾지 못한 태스크에 LONG_MIN을 반환합니다. 잠근 mm에서 oom_score_adj 최소값·OOM_SKIP·vfork 중인 경우도 제외하며 잠금을 풉니다. 기본 점수는 RSS 페이지 수+swap 엔트리 수+페이지 테이블 바이트/PAGE_SIZE입니다. unlock 뒤 oom_score_adj에 totalpages/1000을 곱해 더합니다. 점수 함수 자체가 프로세스를 죽이거나 가장 높은 후보를 선택하는 전체 알고리즘은 아닙니다.
 * RSS=1000,swap=200,페이지 테이블=10페이지,totalpages=10000,adj=100이면 기본1210+보정1000=2210입니다. CPU 사용률은 이 식에 없다는 점도 적으세요.
 */
long oom_badness(struct task_struct *p, unsigned long totalpages)
{
	long points;
	long adj;

	if (oom_unkillable_task(p))
		return LONG_MIN;

	p = find_lock_task_mm(p);
	if (!p)
		return LONG_MIN;

	/*
	 * Do not even consider tasks which are explicitly marked oom
	 * unkillable or have been already oom reaped or the are in
	 * the middle of vfork
	 */
	adj = (long)p->signal->oom_score_adj;
	if (adj == OOM_SCORE_ADJ_MIN ||
			test_bit(MMF_OOM_SKIP, &p->mm->flags) ||
			in_vfork(p)) {
		task_unlock(p);
		return LONG_MIN;
	}

	/*
	 * The baseline for the badness score is the proportion of RAM that each
	 * task's rss, pagetable and swap space use.
	 */

/* 학습 해설
 * 파일시스템 등록: 이름 목록과 마운트된 인스턴스의 차이
 * 커널은 ext4 같은 종류를 알아야 마운트 요청을 해당 구현으로 전달할 수 있지만 종류 등록과 실제 디스크 마운트는 별도 작업입니다.
 * register_filesystem은 parameters가 있으면 설명을 검증하고 실패 시 -EINVAL입니다. 이름의 점 문자는 BUG_ON 조건이고 fs->next가 이미 있으면 -EBUSY입니다. 쓰기 잠금 안에서 같은 이름을 찾아 있으면 -EBUSY, 없으면 찾은 링크 위치에 fs를 연결합니다. find_filesystem은 포인터의 포인터를 반환해 빈 목록과 목록 끝의 연결을 같은 대입으로 처리합니다. 등록한 구조체는 복사되지 않으므로 등록 중 해제하면 안 됩니다.
 * 목록 A→B→NULL에서 C를 추가할 때 p가 B.next의 주소를 가리키고 *p=C가 되는 모습을 그리세요. 같은 이름의 C 재등록이 거절되는 이유를 설명하세요.
 */
int register_filesystem(struct file_system_type * fs)
{
	int res = 0;
	struct file_system_type ** p;

	if (fs->parameters &&
	    !fs_validate_description(fs->name, fs->parameters))
		return -EINVAL;

	BUG_ON(strchr(fs->name, '.'));
	if (fs->next)
		return -EBUSY;
	write_lock(&file_systems_lock);
	p = find_filesystem(fs->name, strlen(fs->name));
	if (*p)
		res = -EBUSY;
	else
		*p = fs;
	write_unlock(&file_systems_lock);
	return res;
}

EXPORT_SYMBOL(register_filesystem);

/**
 *	unregister_filesystem - unregister a file system
 *	@fs: filesystem to unregister
 *
 *	Remove a file system that was previously successfully registered
 *	with the kernel. An error is returned if the file system is not found.
 *	Zero is returned on a success.
 *	
 *	Once this function has returned the &struct file_system_type structure
 *	may be freed or reused.
 */

/* 학습 해설
 * 파일시스템 등록 해제: 연결 삭제 후 RCU 독자를 기다리기
 * 목록에서 객체를 빼도 이미 객체를 읽던 코드가 남아 있을 수 있어 즉시 메모리를 재사용하면 오래된 포인터 접근이 생길 수 있습니다.
 * 쓰기 잠금 아래 포인터의 포인터로 목록을 순회합니다. 이름이 아니라 fs 객체 주소가 같은 항목을 찾으면 이전 링크를 fs->next로 바꾸고 fs->next=NULL로 만든 뒤 잠금을 풉니다. 이후 synchronize_rcu를 호출하고 0입니다. 끝까지 없으면 잠금을 풀고 -EINVAL이며 그 실패 경로에는 RCU 대기가 없습니다. 함수 자체가 fs를 kfree하지는 않습니다.
 * A→B→C에서 B를 제거하면 A.next=C가 되고 B.next=NULL이 됩니다. 목록 제거, unlock, RCU 대기, 반환 순서를 표시하세요.
 */
int unregister_filesystem(struct file_system_type * fs)
{
	struct file_system_type ** tmp;

	write_lock(&file_systems_lock);
	tmp = &file_systems;
	while (*tmp) {
		if (fs == *tmp) {
			*tmp = fs->next;
			fs->next = NULL;
			write_unlock(&file_systems_lock);
			synchronize_rcu();
			return 0;
		}
		tmp = &(*tmp)->next;
	}
	write_unlock(&file_systems_lock);

	return -EINVAL;
}

EXPORT_SYMBOL(unregister_filesystem);

#ifdef CONFIG_SYSFS_SYSCALL
static int fs_index(const char __user * __name)
{

/* 학습 해설
 * IPv4 문자열 변환: 10진수 누적·8비트 이동·입력 검증의 차이
 * 사람이 쓰는 점으로 구분된 주소를 패킷의 32비트 값으로 바꾸려면 각 부분을 숫자로 누적하고 바이트 순서를 맞춰야 합니다.
 * in_aton은 네 번 반복하며 결과를 왼쪽으로 8비트 이동합니다. 각 부분은 val=val*10+문자-0으로 누적하고 점·개행·문자열 끝에서 멈춘 뒤 OR합니다. 마지막 htonl로 네트워크 바이트 순서로 반환합니다. 이 오래된 helper에는 각 문자가 숫자인지, 값이 255 이하인지, 정확히 네 부분인지 검증하는 분기가 없습니다. 임의 외부 입력에 안전한 검증 parser로 사용해서는 안 됩니다.
 * 1.2.3.4의 누적 값이 1→0x0102→0x010203→0x01020304가 되는 과정을 쓰세요. 마지막 htonl은 화면 문자열을 만드는 함수가 아니라 저장할 바이트 순서를 맞추는 함수입니다.
 */
__be32 in_aton(const char *str)
{
	unsigned int l;
	unsigned int val;
	int i;

	l = 0;
	for (i = 0; i < 4; i++)	{
		l <<= 8;
		if (*str != '\0') {
			val = 0;
			while (*str != '\0' && *str != '.' && *str != '\n') {
				val *= 10;
				val += *str - '0';
				str++;
			}
			l |= val;
			if (*str != '\0')
				str++;
		}
	}
	return htonl(l);
}
EXPORT_SYMBOL(in_aton);

#define IN6PTON_XDIGIT		0x00010000

/* 학습 해설
 * 낮은 주소 매핑 제한: 두 정책의 최댓값과 쓰기 권한
 * 낮은 가상 주소 사용 제한을 관리할 때 서로 다른 보안 정책 중 한쪽 값만 낮춰 다른 정책까지 약화시키면 안 됩니다.
 * update_mmap_min_addr는 LSM 최소값이 설정된 빌드에서는 DAC 값과 LSM 값의 큰 쪽을 사용하고, 없으면 DAC 값만 사용합니다. sysctl handler는 쓰기 요청이며 CAP_SYS_RAWIO가 없으면 -EPERM입니다. 통과하면 proc_doulongvec_minmax로 읽기·쓰기 처리를 위임하고 결과와 관계없이 유효 최소값을 다시 계산한 뒤 그 결과 코드를 반환합니다. 초기화 helper도 같은 계산을 수행합니다. 이 코드는 모든 mmap 요청의 최종 허용 여부를 직접 판정하는 전체 보안 경로는 아닙니다.
 * DAC=4096,LSM=65536이면 유효값65536입니다. DAC만1024로 낮춰도 LSM 기준 때문에 유효값은65536입니다. 권한 없는 쓰기는 값 처리 helper까지 가지 않음을 표시하세요.
 */
int mmap_min_addr_handler(const struct ctl_table *table, int write,
			  void *buffer, size_t *lenp, loff_t *ppos)
{
	int ret;

	if (write && !capable(CAP_SYS_RAWIO))
		return -EPERM;

	ret = proc_doulongvec_minmax(table, write, buffer, lenp, ppos);

	update_mmap_min_addr();

	return ret;
}

static int __init init_mmap_min_addr(void)
{
	update_mmap_min_addr();

	return 0;
}
pure_initcall(init_mmap_min_addr);

/* 학습 해설
 * 저장장치 제한 갱신: 복사본 검증과 한 번의 반영
 * 저장장치는 한 번에 받을 수 있는 요청 크기와 정렬 조건이 있습니다. 여러 설정 중 절반만 바뀐 상태로 다른 요청이 처리되면 서로 맞지 않는 조건을 적용할 수 있습니다. 그래서 수정할 값들을 모아 검증한 뒤 실제 큐에 반영합니다.
 * queue_limits_start_update는 limits_lock이라는 mutex를 잡고 기존 q->limits의 구조체 복사본을 반환합니다. 호출자는 그 복사본을 수정합니다. commit은 blk_validate_limits로 검사하고 오류면 실제 q->limits 대입을 건너뜁니다. CONFIG_BLK_INLINE_ENCRYPTION 빌드에서 crypto_profile과 integrity.tag_size가 함께 있으면 -EINVAL입니다. 모두 통과하면 q->limits = *lim으로 복사하고 disk가 있으면 BDI 제한도 갱신합니다. 성공과 실패 모두 마지막에 mutex를 풀고 결과를 반환합니다.
 * 원래 최대 요청 크기가 128이고 수정 복사본이 잘못된 값이라고 가정해 보세요. 검증 실패 시 원래 큐는 128을 유지하고 잠금은 풀립니다. 커널 호출 순서는 start_update → 복사본 수정 → commit입니다. 수정 도중 중단할 때는 queue_limits_cancel_update로 잠금을 해제합니다. 이것은 사용자 프로그램에서 직접 호출할 API가 아닙니다.
 */
int queue_limits_commit_update(struct request_queue *q,
		struct queue_limits *lim)
{
	int error;

	error = blk_validate_limits(lim);
	if (error)
		goto out_unlock;

#ifdef CONFIG_BLK_INLINE_ENCRYPTION
	if (q->crypto_profile && lim->integrity.tag_size) {
		pr_warn("blk-integrity: Integrity and hardware inline encryption are not supported together.\n");
		error = -EINVAL;
		goto out_unlock;
	}
#endif

	q->limits = *lim;
	if (q->disk)
		blk_apply_bdi_limits(q->disk->bdi, lim);
out_unlock:
	mutex_unlock(&q->limits_lock);
	return error;
}
EXPORT_SYMBOL_GPL(queue_limits_commit_update);

/* 학습 해설
 * IPC 접근 권한: 비트 이동과 누락된 권한 찾기
 * 공유 메모리나 메시지 큐는 여러 프로세스가 함께 쓰므로 누가 읽고 쓸 수 있는지 판단해야 합니다. 소유자·그룹·그 외 사용자의 권한을 비트로 저장하면 필요한 권한이 모두 있는지를 작은 비트 연산으로 검사할 수 있습니다.
 * ipcperms는 현재 유효 UID를 얻고 audit_ipc_obj를 호출합니다. requested_mode는 (flag >> 6) | (flag >> 3) | flag로 요청 비트를 낮은 세 비트로 모읍니다. 현재 사용자가 생성자나 소유자면 mode를 6비트, 관련 그룹에 속하면 3비트 이동하고 나머지는 그대로 둡니다. requested_mode & ~granted_mode & 0007은 요청했지만 부여되지 않은 비트입니다. 이것이 있고 해당 user namespace에서 CAP_IPC_OWNER도 없으면 -1입니다. 그 검사를 통과해도 security_ipc_permission의 결과를 반환하므로 LSM 정책이 거절할 수 있습니다.
 * 읽기를 이진수 100, 쓰기를 010으로 놓으세요. 요청 110과 부여 100이면 110 & ~100 & 111 = 010입니다. 쓰기 권한이 부족한 것입니다. C의 0007은 8진수 표기이며 값은 7, 이진수는 111입니다. 소유자인데 소유자 비트가 부족하면 더 넓은 그룹 비트로 다시 시도하는 코드가 아님도 확인하세요.
 */
int ipcperms(struct ipc_namespace *ns, struct kern_ipc_perm *ipcp, short flag)
{
	kuid_t euid = current_euid();
	int requested_mode, granted_mode;

	audit_ipc_obj(ipcp);
	requested_mode = (flag >> 6) | (flag >> 3) | flag;
	granted_mode = ipcp->mode;
	if (uid_eq(euid, ipcp->cuid) ||
	    uid_eq(euid, ipcp->uid))
		granted_mode >>= 6;
	else if (in_group_p(ipcp->cgid) || in_group_p(ipcp->gid))
		granted_mode >>= 3;
	/* is there some bit set in requested_mode but not in granted_mode? */
	if ((requested_mode & ~granted_mode & 0007) &&
	    !ns_capable(ns->user_ns, CAP_IPC_OWNER))
		return -1;

	return security_ipc_permission(ipcp, flag);
}

/*
 * Functions to convert between the kern_ipc_perm structure and the
 * old/new ipc_perm structures
 */

/* 학습 해설
 * IPC 식별자: 재사용된 번호를 세대 값으로 구별하기
 * 객체 A가 쓰던 번호 5를 해제한 뒤 객체 B가 다시 쓰면 예전에 A의 번호를 기억한 프로세스가 B를 잘못 찾을 수 있습니다. 번호만 비교하면 과거 객체와 현재 객체를 구별할 정보가 없기 때문입니다.
 * ipc_obtain_object_idr는 id에서 ipcid_to_idx로 인덱스를 꺼내 IDR에서 객체를 찾습니다. 없으면 ERR_PTR(-EINVAL)을 반환합니다. ipc_obtain_object_check는 그 오류 포인터를 IS_ERR로 검사해 그대로 반환하고, 성공한 객체에서는 ipc_checkid로 ID의 sequence와 객체 seq를 비교합니다. 다르면 -EINVAL 오류 포인터, 같으면 객체 포인터입니다. ipc/util.h에서 ipcid_to_idx는 마스크, ipcid_to_seqx는 오른쪽 비트 이동으로 두 부분을 분리합니다. 비트 배치는 설정에 따라 달라질 수 있습니다.
 * 실제 비트 폭 대신 (인덱스, 세대) 표기로 계산하세요. 오래된 ID=(5,2), 현재 객체=(5,3)이면 IDR 조회는 성공해도 세대 비교가 실패합니다. (5,3)이면 그 검사를 통과합니다. 두 helper는 RCU 읽기 구간 안에서 호출해야 하며 반환할 때 객체 잠금이 잡혀 있지 않다는 원문 계약을 같이 적으세요.
 */
struct kern_ipc_perm *ipc_obtain_object_check(struct ipc_ids *ids, int id)
{
	struct kern_ipc_perm *out = ipc_obtain_object_idr(ids, id);

	if (IS_ERR(out))
		goto out;

	if (ipc_checkid(out, id))
		return ERR_PTR(-EINVAL);
out:
	return out;
}

/**
 * ipcget - Common sys_*get() code
 * @ns: namespace
 * @ids: ipc identifier set
 * @ops: operations to be called on ipc object creation, permission checks
 *       and further checks
 * @params: the parameters needed by the previous operations.
 *
 * Common routine called by sys_msgget(), sys_semget() and sys_shmget().
 */
int ipcget(struct ipc_namespace *ns, struct ipc_ids *ids,
			const struct ipc_ops *ops, struct ipc_params *params)
{

/* 학습 해설
 * KVM 가상머신 수명: 참조 수와 0에서 되살리지 않기
 * 가상머신 객체를 vCPU나 장치 같은 여러 구성 요소가 함께 사용합니다. 한 구성 요소의 일이 끝났다고 즉시 VM을 해제하면 다른 구성 요소가 아직 쓰는 포인터가 해제된 메모리를 가리키게 됩니다. 참조 수는 아직 객체가 필요하다는 소유 관계를 센 값입니다.
 * kvm_get_kvm은 users_count를 증가시킵니다. kvm_get_kvm_safe는 refcount_inc_not_zero로 0이 아닐 때만 증가시키고 성공 여부를 돌려줍니다. kvm_put_kvm은 감소 후 0인지 검사해 마지막 참조일 때 kvm_destroy_vm을 부릅니다. kvm_put_kvm_no_destroy는 감소 결과가 0이면 WARN_ON을 내며 destroy를 호출하지 않습니다. 파일 descriptor 설치 실패처럼 별도 소유자가 아직 남아 있어야 하는 경로의 참조 반환을 위한 함수입니다.
 * 2개의 참조가 있는 VM에서 put을 한 번 하면 1이라 파괴하지 않고, 한 번 더 하면 0이라 destroy 경로로 갑니다. 반면 수가 0인 살아 있는 참조 카운터에 safe get을 하면 false이며 1로 바뀌지 않습니다. 가상머신을 종료하는 shell 명령이 아니라 커널 내부 객체 수명의 API라는 점을 구분하세요.
 */
bool kvm_get_kvm_safe(struct kvm *kvm)
{
	return refcount_inc_not_zero(&kvm->users_count);
}
EXPORT_SYMBOL_GPL(kvm_get_kvm_safe);

void kvm_put_kvm(struct kvm *kvm)
{
	if (refcount_dec_and_test(&kvm->users_count))
		kvm_destroy_vm(kvm);
}
EXPORT_SYMBOL_GPL(kvm_put_kvm);

/*
 * Used to put a reference that was taken on behalf of an object associated
 * with a user-visible file descriptor, e.g. a vcpu or device, if installation
 * of the new file descriptor fails and the reference cannot be transferred to
 * its final owner.  In such cases, the caller is still actively using @kvm and
 * will fail miserably if the refcount unexpectedly hits zero.
 */
void kvm_put_kvm_no_destroy(struct kvm *kvm)
{
	WARN_ON(refcount_dec_and_test(&kvm->users_count));
}
EXPORT_SYMBOL_GPL(kvm_put_kvm_no_destroy);

/* 학습 해설
 * KVM 메모리 슬롯: 게스트 프레임 번호로 정렬한 레드블랙 트리
 * 가상머신의 메모리 슬롯은 여러 게스트 페이지를 하나의 범위로 나타냅니다. 슬롯이 많을 때 정렬되지 않은 목록을 처음부터 훑으면 비교 횟수가 슬롯 수에 비례합니다. 시작 게스트 프레임 번호를 기준으로 균형 트리를 유지하면 비교할 후보를 단계적으로 줄일 수 있습니다.
 * kvm_insert_gfn_node는 slots->node_idx로 사용할 gfn_node를 고르고 gfn_tree의 루트 링크부터 내려갑니다. container_of는 rb_node를 포함하는 kvm_memory_slot의 주소를 구합니다. 새 base_gfn이 작으면 왼쪽 링크, 크면 오른쪽 링크로 이동하고 같으면 BUG입니다. 빈 링크에 도달하면 rb_link_node로 부모와 자식 링크를 연결하고 rb_insert_color로 균형 조건을 복구합니다. 이 함수는 삽입용이며 해당 GFN이 슬롯 범위에 포함되는지 조회하는 전체 함수는 아닙니다.
 * 시작 GFN 100이 루트라고 가정하고 40을 넣으면 왼쪽, 160을 넣으면 오른쪽 후보로 갑니다. 120은 100의 오른쪽에서 160보다 작아 왼쪽 빈 링크를 찾습니다. 이것은 삽입 위치 탐색 예제이고 실제 최종 모양은 균형 조정으로 바뀔 수 있습니다. base_gfn은 페이지 번호이며 바이트 주소와 바로 비교하지 않습니다.
 */
static void kvm_insert_gfn_node(struct kvm_memslots *slots,
				struct kvm_memory_slot *slot)
{
	struct rb_root *gfn_tree = &slots->gfn_tree;
	struct rb_node **node, *parent;
	int idx = slots->node_idx;

	parent = NULL;
	for (node = &gfn_tree->rb_node; *node; ) {
		struct kvm_memory_slot *tmp;

		tmp = container_of(*node, struct kvm_memory_slot, gfn_node[idx]);
		parent = *node;
		if (slot->base_gfn < tmp->base_gfn)
			node = &(*node)->rb_left;
		else if (slot->base_gfn > tmp->base_gfn)
			node = &(*node)->rb_right;
		else
			BUG();
	}

	rb_link_node(&slot->gfn_node[idx], parent, node);
	rb_insert_color(&slot->gfn_node[idx], gfn_tree);
}

static void kvm_erase_gfn_node(struct kvm_memslots *slots,

/* 학습 해설
 * 스케줄러 깨움 상태: 성공했어도 바로 실행하지 않는 경우
 * 잠든 태스크를 깨우는 요청과 태스크가 기다리는 이유가 항상 같지는 않습니다. 일반 이벤트를 기다리던 태스크가 잠시 RT 잠금 때문에 기다리게 되어도 원래 이벤트의 깨움 요청을 잃으면 안 됩니다.
