/* 학습 해설
 * 타임아웃 대기: 남은 시간과 스택 타이머 정리
 * 태스크를 일정 시간 기다리게 할 때 다른 이벤트가 먼저 발생할 수 있습니다. 또한 함수 안의 스택에 타이머를 만들었다면 함수가 반환한 뒤 그 타이머 콜백이 스택을 다시 읽지 못하도록 정리해야 합니다.
 * schedule_timeout은 MAX_SCHEDULE_TIMEOUT이면 타이머 없이 schedule을 부르고 같은 값을 반환합니다. 음수는 오류 로그와 스택을 출력하고 TASK_RUNNING으로 고친 뒤 0을 반환합니다. 일반 값은 현재 jiffies에 timeout을 더해 만료점을 만들고 process_timer에 current를 저장합니다. 스택 타이머를 설정·등록한 뒤 schedule합니다. 돌아오면 del_timer_sync로 콜백과 동기화해 제거하고 destroy_timer_on_stack으로 추적을 정리합니다. 남은 expire-jiffies를 계산하되 음수면 0입니다. 콜백 process_timeout은 저장한 task를 wake_up_process로 깨웁니다.
 * 시작 jiffies=1000, timeout=50이면 만료점은 1050입니다. 명시적 깨움 뒤 1020에 돌아오면 30, 만료 후 1053에 돌아오면 0입니다. 단위는 밀리초가 아니라 jiffies입니다. 호출 전 TASK_RUNNING이면 CPU 스케줄링은 거쳐도 태스크를 잠든 상태로 만들지 않으므로 적절한 상태 지정이나 wrapper가 필요합니다.
 */
signed long __sched schedule_timeout(signed long timeout)
{
	struct process_timer timer;
	unsigned long expire;

	switch (timeout)
	{
	case MAX_SCHEDULE_TIMEOUT:
		/*
		 * These two special cases are useful to be comfortable
		 * in the caller. Nothing more. We could take
		 * MAX_SCHEDULE_TIMEOUT from one of the negative value
		 * but I' d like to return a valid offset (>=0) to allow
		 * the caller to do everything it want with the retval.
		 */
		schedule();
		goto out;
	default:
		/*
		 * Another bit of PARANOID. Note that the retval will be
		 * 0 since no piece of kernel is supposed to do a check
		 * for a negative retval of schedule_timeout() (since it
		 * should never happens anyway). You just have the printk()
		 * that will tell you if something is gone wrong and where.
		 */
		if (timeout < 0) {

/* 학습 해설
 * 밀리초 대기: 일찍 깨어나면 남은 시간으로 반복하기
 * 한 번 대기 함수를 호출했다고 요청한 기간을 모두 기다렸다고 볼 수는 없습니다. 명시적 깨움이나 신호 때문에 돌아올 수 있어 대기 목적에 따라 남은 시간을 다시 기다리거나 호출자에게 돌려줘야 합니다.
 * msleep은 msecs_to_jiffies로 단위를 바꾸고 timeout이 남아 있는 동안 schedule_timeout_uninterruptible의 반환값을 새 timeout으로 사용합니다. msleep_interruptible은 신호가 없는 동안만 schedule_timeout_interruptible을 반복하고 남은 jiffies를 밀리초로 변환해 반환합니다. timeout wrapper들은 각각 TASK_UNINTERRUPTIBLE과 TASK_INTERRUPTIBLE을 설정한 뒤 공통 schedule_timeout을 호출합니다. TASK_KILLABLE과 TASK_IDLE wrapper도 같은 구조이며 idle은 load average에 기여하지 않는 대기 상태입니다.
 * 변환된 timeout=10에서 첫 대기가 4를 반환하면 다음에는 10이 아니라 4를 넘깁니다. 다시 0이면 종료합니다. interruptible 버전에서 신호가 이미 pending이면 while 본체를 실행하지 않고 변환한 남은 시간을 반환합니다. 반환 단위와 jiffies 변환 반올림 때문에 요청 밀리초가 모든 설정에서 그대로 보존된다고 가정하지 마세요.
 */
void msleep(unsigned int msecs)
{
	unsigned long timeout = msecs_to_jiffies(msecs);

	while (timeout)
		timeout = schedule_timeout_uninterruptible(timeout);
}

EXPORT_SYMBOL(msleep);

/**
 * msleep_interruptible - sleep waiting for signals
 * @msecs: Time in milliseconds to sleep for
 */
unsigned long msleep_interruptible(unsigned int msecs)
{
	unsigned long timeout = msecs_to_jiffies(msecs);

	while (timeout && !signal_pending(current))
		timeout = schedule_timeout_interruptible(timeout);
	return jiffies_to_msecs(timeout);
}

EXPORT_SYMBOL(msleep_interruptible);

/**
 * usleep_range_state - Sleep for an approximate time in a given state
 * @min:	Minimum time in usecs to sleep
 * @max:	Maximum time in usecs to sleep
 * @state:	State of the current task that will be while sleeping
 *
 * In non-atomic context where the exact wakeup time is flexible, use
 * usleep_range_state() instead of udelay().  The sleep improves responsiveness
 * by avoiding the CPU-hogging busy-wait of udelay(), and the range reduces
 * power usage by allowing hrtimers to take advantage of an already-
 * scheduled interrupt instead of scheduling a new one just for this sleep.
 */

/* 학습 해설
 * 런타임 전원 참조: 이미 켜진 장치만 붙잡기
 * 장치가 이미 작동 중이라면 잠깐 사용이 끝날 때까지 절전 진입을 막고 싶지만, 꺼진 장치를 새로 깨울 필요는 없을 수 있습니다. 이 조건부 사용 참조는 재개 요청과 다른 역할입니다.
 * pm_runtime_get_conditional은 power.lock을 IRQ 저장과 함께 잡습니다. disable_depth가 양수면 -EINVAL, runtime_status가 RPM_ACTIVE가 아니면 0입니다. active일 때 ign_usage_count가 참이면 usage_count를 증가하고 1입니다. 거짓이면 atomic_inc_not_zero 결과를 돌려줍니다. 모든 분기에서 trace_rpm_usage 후 잠금을 풀고 IRQ 상태를 복원합니다. pm_runtime_get_if_active는 true, pm_runtime_get_if_in_use는 false를 전달합니다.
 * PM 활성·장치 active·usage_count=0이면 get_if_active는 1로 증가하며 성공하지만 get_if_in_use는 0을 유지하며 실패합니다. count=2이면 둘 다 3으로 증가할 수 있습니다. 반환값이 양수일 때만 새 사용 참조를 얻었으므로 사용을 마치면 대응하는 runtime PM 반환 경로로 내려놓아야 합니다.
 */
static int pm_runtime_get_conditional(struct device *dev, bool ign_usage_count)
{
	unsigned long flags;
	int retval;

	spin_lock_irqsave(&dev->power.lock, flags);
	if (dev->power.disable_depth > 0) {
		retval = -EINVAL;
	} else if (dev->power.runtime_status != RPM_ACTIVE) {
		retval = 0;
	} else if (ign_usage_count) {
		retval = 1;
		atomic_inc(&dev->power.usage_count);
	} else {
		retval = atomic_inc_not_zero(&dev->power.usage_count);
	}
	trace_rpm_usage(dev, 0);
	spin_unlock_irqrestore(&dev->power.lock, flags);

	return retval;
}

/**
 * pm_runtime_get_if_active - Bump up runtime PM usage counter if the device is
 *			      in active state
 * @dev: Target device.
 *
 * Increment the runtime PM usage counter of @dev if its runtime PM status is
 * %RPM_ACTIVE, in which case it returns 1. If the device is in a different
 * state, 0 is returned. -EINVAL is returned if runtime PM is disabled for the
 * device, in which case also the usage_count will remain unmodified.
 */

/* 학습 해설
 * 절전 진입 경쟁: 깨움 이벤트 수를 읽고 다시 확인하기
 * 절전 준비를 마친 직후 입력 이벤트가 들어오면 그 이벤트를 처리하기도 전에 시스템이 잠들 수 있습니다. 준비 전후의 이벤트 수를 비교하고 진행 중인 이벤트도 확인하면 이런 경쟁을 감지할 수 있습니다.
 * pm_save_wakeup_count는 이벤트 검사 활성 표시를 false로 만들고 events_lock을 잡습니다. split_counters로 누적 이벤트 cnt와 처리 중인 이벤트 inpr을 읽습니다. 전달한 count가 현재 cnt와 같고 inpr이 0일 때만 saved_count를 저장하고 검사를 활성화합니다. 잠금을 풀고 그 활성 여부를 반환합니다. pm_get_wakeup_count의 block=true는 처리 중 이벤트가 없거나 신호가 pending일 때까지 interruptible 대기하고 마지막에 수를 다시 읽어 inpr==0인지 반환합니다.
 * 준비 전 count=20을 읽었는데 저장 시 현재 cnt=21이면 실패입니다. cnt=20이어도 inpr=1이면 실패입니다. cnt=20이고 inpr=0이어야 성공합니다. 사용자 공간 프로토콜은 wakeup_count 읽기 → 준비 → 같은 값 쓰기 → 성공한 경우 state 요청입니다. 이 수업에서는 실제 시스템을 절전시키는 쓰기를 실행하지 않습니다.
 */
bool pm_save_wakeup_count(unsigned int count)
{
	unsigned int cnt, inpr;
	unsigned long flags;

	events_check_enabled = false;
	raw_spin_lock_irqsave(&events_lock, flags);
	split_counters(&cnt, &inpr);
	if (cnt == count && inpr == 0) {
		saved_count = count;
		events_check_enabled = true;
	}
	raw_spin_unlock_irqrestore(&events_lock, flags);
	return events_check_enabled;
}

#ifdef CONFIG_PM_AUTOSLEEP
/**
 * pm_wakep_autosleep_enabled - Modify autosleep_enabled for all wakeup sources.
 * @set: Whether to set or to clear the autosleep_enabled flags.
 */
void pm_wakep_autosleep_enabled(bool set)
{
	struct wakeup_source *ws;
	ktime_t now = ktime_get();
	int srcuidx;

/* 학습 해설
 * 시스템 절전 요청: 문자열 해석과 자동 절전의 충돌
 * 사용자가 절전 상태를 요청하는 동안 자동 절전 정책도 동작하면 서로 충돌할 수 있습니다. 문자열을 단순히 하드웨어 명령으로 바꾸기 전에 지원 상태와 정책 직렬화가 필요합니다.
 * state_store는 pm_autosleep_lock 실패면 바로 반환합니다. 자동 절전 상태가 PM_SUSPEND_ON보다 크면 -EBUSY로 공통 해제 지점에 갑니다. decode_state로 입력을 해석하고 suspend 범위이면 mem 요청을 mem_sleep_current로 바꾸어 pm_suspend를 부릅니다. PM_SUSPEND_MAX는 disk를 나타내는 경계 값으로 hibernate에 연결합니다. 나머지는 -EINVAL입니다. 마지막에는 autosleep 잠금을 풀고 오류면 오류, 성공이면 입력 길이 n을 반환합니다.
 * decode_state는 첫 개행까지의 길이를 사용합니다. 길이 4의 disk는 hibernation 경계 값이 되고, suspend 이름은 pm_states에 있는 문자열과 길이까지 같아야 합니다. 지원 이름 목록은 state_show가 출력하며 끝의 공백을 개행으로 바꿉니다. 모르는 이름은 PM_SUSPEND_ON으로 해석되어 suspend 호출 경로의 유효성 검사에서 거절됩니다. 이 wrapper가 직접 모든 하드웨어 절전 단계를 구현하지 않습니다.
 */
static ssize_t state_store(struct kobject *kobj, struct kobj_attribute *attr,
			   const char *buf, size_t n)
{
	suspend_state_t state;
	int error;

	error = pm_autosleep_lock();
	if (error)
		return error;

	if (pm_autosleep_state() > PM_SUSPEND_ON) {
		error = -EBUSY;
		goto out;
	}

	state = decode_state(buf, n);
	if (state < PM_SUSPEND_MAX) {
		if (state == PM_SUSPEND_MEM)
			state = mem_sleep_current;

		error = pm_suspend(state);
	} else if (state == PM_SUSPEND_MAX) {
		error = hibernate();
	} else {
		error = -EINVAL;
	}

/* 학습 해설
 * SysV 메시지 할당: 큰 본문을 연결된 조각에 나누기
 * 긴 메시지를 헤더와 함께 하나의 큰 연속 할당으로 만들면 큰 공간을 한 번에 확보해야 합니다. 이 구현은 처음 메시지 헤더 뒤와 연결된 작은 조각들 뒤에 본문을 나누어 저장합니다. 각 조각의 next 포인터로 순서를 유지합니다.
 * DATALEN_MSG는 PAGE_SIZE에서 msg_msg 헤더 크기를 뺀 값이고 DATALEN_SEG는 msg_msgseg 헤더 크기를 뺀 값입니다. alloc_msg는 처음 본문 길이를 min으로 제한해 kmem_buckets_alloc으로 헤더와 본문을 함께 확보합니다. next와 security를 NULL로 초기화한 뒤 남은 길이를 반복 처리합니다. 각 반복에서 cond_resched 후 조각을 할당하고 포인터의 포인터 pseg로 연결한 뒤 pseg를 새 조각의 next 주소로 옮깁니다. 중간 실패는 free_msg로 이미 만든 전체 연결을 정리하고 NULL입니다.
 * PAGE_SIZE=4096, 메시지 헤더=48, 조각 헤더=8바이트라고 가정하세요. 본문 9000바이트는 처음 4048, 다음 4088, 마지막 864바이트로 나뉩니다. 요청 할당량은 4096+4096+872=9064바이트이며 allocator 자체 관리 비용은 이 계산에 없습니다. 실제 헤더 크기는 구조체와 아키텍처로 확인해야 합니다.
 */
static struct msg_msg *alloc_msg(size_t len)
{
	struct msg_msg *msg;
	struct msg_msgseg **pseg;
	size_t alen;

	alen = min(len, DATALEN_MSG);
	msg = kmem_buckets_alloc(msg_buckets, sizeof(*msg) + alen, GFP_KERNEL);
	if (msg == NULL)
		return NULL;

	msg->next = NULL;
	msg->security = NULL;

	len -= alen;
	pseg = &msg->next;
	while (len > 0) {
		struct msg_msgseg *seg;

		cond_resched();

		alen = min(len, DATALEN_SEG);
		seg = kmalloc(sizeof(*seg) + alen, GFP_KERNEL_ACCOUNT);
		if (seg == NULL)
			goto out_err;
		*pseg = seg;

/* 학습 해설
 * SysV 메시지 입력: 사용자 복사 실패와 보안 초기화
 * 사용자 공간 주소는 복사 도중 접근할 수 없는 페이지를 만날 수 있습니다. 메시지를 위해 메모리를 확보했다는 것과 사용자 본문 복사 및 보안 초기화가 성공했다는 것은 각각 확인해야 합니다.
 * load_msg는 alloc_msg 실패면 ERR_PTR(-ENOMEM)입니다. 처음 msg+1 뒤로 첫 본문을 copy_from_user하고 반환이 0이 아니면 공통 정리로 갑니다. 이어 각 seg+1로 복사하며 이전 복사 길이만큼 len을 줄이고 src를 이동합니다. 본문 복사 후 security_msg_msg_alloc을 호출하고 오류면 역시 free_msg합니다. 복사 실패의 기본 err는 -EFAULT이며 보안 hook 이후에는 그 hook의 오류가 저장됩니다. 성공하면 msg를 반환합니다.
 * 첫 4048바이트 복사 성공 후 다음 조각에서 실패했다고 가정하세요. 이미 복사한 메시지 일부를 반환하지 않고 모든 메시지 할당을 정리해 -EFAULT 오류 포인터를 돌려줍니다. 사용자에게서 가져온 데이터가 유효한 메시지 타입인지와 큐 제한을 만족하는지는 이 helper 바깥의 송신 경로와 구분하세요.
 */
struct msg_msg *load_msg(const void __user *src, size_t len)
{
	struct msg_msg *msg;
	struct msg_msgseg *seg;
	int err = -EFAULT;
	size_t alen;

	msg = alloc_msg(len);
	if (msg == NULL)
		return ERR_PTR(-ENOMEM);

	alen = min(len, DATALEN_MSG);
	if (copy_from_user(msg + 1, src, alen))
		goto out_err;

	for (seg = msg->next; seg != NULL; seg = seg->next) {
		len -= alen;
		src = (char __user *)src + alen;
		alen = min(len, DATALEN_SEG);
		if (copy_from_user(seg + 1, src, alen))
			goto out_err;
	}

	err = security_msg_msg_alloc(msg);
	if (err)
		goto out_err;

/* 학습 해설
 * SysV 메시지 복사와 출력: 커널 복사·사용자 복사의 계약
 * 커널 안의 메시지를 복제하는 작업과 사용자 버퍼로 내보내는 작업은 주소 공간과 실패 방식이 다릅니다. 같은 조각 연결을 순회해도 어떤 길이가 보장되어야 하고 오류를 어떻게 표현하는지 따로 읽어야 합니다.
 * store_msg는 첫 본문과 연결 조각을 차례로 copy_to_user합니다. 조각으로 이동할 때 len을 줄이고 dest를 char __user 포인터 기준으로 이동합니다. 하나라도 복사 실패면 -1, 끝까지 가면 0입니다. CONFIG_CHECKPOINT_RESTORE의 copy_msg는 src->m_ts가 dst->m_ts보다 크면 -EINVAL 오류 포인터입니다. 아니면 memcpy로 본문 조각을 복사한 뒤 m_type과 m_ts를 복사하고 dst를 반환합니다. 설정이 없으면 copy_msg는 -ENOSYS 오류 포인터입니다.
 * store_msg에서 두 번째 조각 복사가 실패하면 반환은 -1이지만 앞서 사용자 버퍼에 기록한 첫 조각이 자동으로 사라지지는 않습니다. copy_msg의 목적지 용량 100, 원본 길이 120이면 복사 전에 거절됩니다. 두 함수 모두 호출자가 올바른 연결과 실제 저장 용량을 제공해야 하며 임의로 만든 포인터 연결을 검증하는 범용 parser가 아닙니다.
 */
int store_msg(void __user *dest, struct msg_msg *msg, size_t len)
{
	size_t alen;
	struct msg_msgseg *seg;

	alen = min(len, DATALEN_MSG);
	if (copy_to_user(dest, msg + 1, alen))
		return -1;

	for (seg = msg->next; seg != NULL; seg = seg->next) {
		len -= alen;
		dest = (char __user *)dest + alen;
		alen = min(len, DATALEN_SEG);
		if (copy_to_user(dest, seg + 1, alen))
			return -1;
	}
	return 0;
}

void free_msg(struct msg_msg *msg)
{
	struct msg_msgseg *seg;

	security_msg_msg_free(msg);

	seg = msg->next;

/* 학습 해설
 * SysV 메시지 해제: 다음 링크를 먼저 저장하는 이유
 * 연결 리스트의 현재 노드를 해제하면 그 노드 안의 next도 더는 읽을 수 없습니다. 다음 주소를 먼저 보관하지 않고 free 후 next를 읽으면 이미 반환한 메모리를 접근하는 오류가 생깁니다.
 * free_msg는 먼저 security_msg_msg_free를 호출합니다. msg->next를 seg에 보관한 뒤 첫 msg를 kfree합니다. 반복마다 seg->next를 tmp에 저장하고 cond_resched 후 현재 seg를 kfree하며 seg=tmp로 이동합니다. 마지막 NULL에서 종료합니다. 이 함수는 정상 전체 메시지뿐 아니라 alloc_msg/load_msg의 중간 실패 정리에서도 사용됩니다. msg 자체가 NULL이면 바로 반환하는 검사 코드는 없습니다.
 * 메시지 머리→A→B→NULL을 그려 보세요. 머리를 지우기 전에 A를, A를 지우기 전에 B를 저장합니다. cond_resched는 긴 연결 정리 중 다른 실행 기회를 줄 수 있는 지점입니다. 이 함수가 메시지를 큐에서 빼거나 다른 참조 사용자가 끝날 때까지 기다려 준다고 가정하지 마세요.
 */
void free_msg(struct msg_msg *msg)
{
	struct msg_msgseg *seg;

	security_msg_msg_free(msg);

	seg = msg->next;
	kfree(msg);
	while (seg != NULL) {
		struct msg_msgseg *tmp = seg->next;

		cond_resched();
		kfree(seg);
		seg = tmp;
	}
}

/* 학습 해설
 * Capability 검사: 현재 자격·네임스페이스·사용 표시
 * 관리 권한을 확인할 때 어떤 태스크의 자격인지, 어느 user namespace에 대한 권한인지가 필요합니다. 컨테이너 안의 권한을 곧바로 시스템 전체의 권한과 같다고 취급하면 검사 대상을 잘못 잡게 됩니다.
 * CONFIG_MULTIUSER 구현의 ns_capable_common은 cap_valid가 아니면 심각한 로그와 BUG를 실행합니다. 유효한 capability이면 current_cred와 대상 ns 및 opts를 security_capable에 전달합니다. 결과 0이면 current->flags에 PF_SUPERPRIV를 OR하고 true, 아니면 false입니다. ns_capable은 CAP_OPT_NONE, noaudit 변형은 CAP_OPT_NOAUDIT, setid 변형은 CAP_OPT_INSETID를 전달합니다. capable은 대상 namespace로 init_user_ns를 선택합니다.
 * 같은 cap 숫자라도 대상 ns가 달라지면 검사 문맥이 달라짐을 표에 적으세요. security_capable의 정수 0은 허용이고 바깥 bool 반환은 true입니다. PF_SUPERPRIV는 확인된 권한의 사용을 표시하는 태스크 플래그이며 새로운 capability를 부여하는 연산이 아닙니다.
 */
static bool ns_capable_common(struct user_namespace *ns,
			      int cap,
			      unsigned int opts)
{
	int capable;

	if (unlikely(!cap_valid(cap))) {
		pr_crit("capable() called with invalid cap=%u\n", cap);
		BUG();
	}

	capable = security_capable(current_cred(), ns, cap, opts);
	if (capable == 0) {
		current->flags |= PF_SUPERPRIV;
		return true;
	}
	return false;
}

/**
 * ns_capable - Determine if the current task has a superior capability in effect
 * @ns:  The usernamespace we want the capability in
 * @cap: The capability to be tested for
 *
 * Return true if the current task has the given superior capability currently
 * available for use, false if not.
 *
 * This sets PF_SUPERPRIV on the task if the capability is available on the
 * assumption that it's about to be used.
 */

/* 학습 해설
 * 열린 파일의 권한 자격: 지금 호출자와 열 때의 자격
 * 파일을 연 뒤 프로세스의 자격이 바뀌거나 파일 descriptor를 다른 프로세스에 전달할 수 있습니다. 어떤 작업은 현재 호출자의 자격 대신 파일을 열 때 보관한 자격을 검사하므로 두 시점을 구별해야 합니다.
 * file_ns_capable은 cap이 유효하지 않으면 WARN_ON_ONCE 후 false입니다. 유효하면 file->f_cred와 대상 ns, cap, CAP_OPT_NONE을 security_capable에 전달하고 0이면 true입니다. current_cred를 직접 가져오지 않으며 PF_SUPERPRIV도 설정하지 않습니다. 현재 사용자가 실제로 특권 태스크가 아닐 수 있기 때문이라는 주석이 있습니다.
 * A가 연 file을 B가 사용하게 된 상황을 그리세요. 이 helper가 전달하는 자격 포인터는 B의 current_cred가 아니라 file에 저장된 f_cred입니다. 이것이 모든 file 작업에서 항상 A 권한만 사용한다는 뜻은 아닙니다. 해당 helper를 선택한 호출 경로의 정책 범위를 따라가야 합니다.
 */
bool file_ns_capable(const struct file *file, struct user_namespace *ns,
		     int cap)
{

	if (WARN_ON_ONCE(!cap_valid(cap)))
		return false;

	if (security_capable(file->f_cred, ns, cap, CAP_OPT_NONE) == 0)
		return true;

	return false;
}
EXPORT_SYMBOL(file_ns_capable);

/**
 * privileged_wrt_inode_uidgid - Do capabilities in the namespace work over the inode?
 * @ns: The user namespace in question
 * @idmap: idmap of the mount @inode was found from
 * @inode: The inode in question
 *
 * Return true if the inode uid and gid are within the namespace.
 */
bool privileged_wrt_inode_uidgid(struct user_namespace *ns,
				 struct mnt_idmap *idmap,
				 const struct inode *inode)
{

/* 학습 해설
 * eventfd 신호: 포화 카운터·대기자 깨움·재진입 차단
 * 이벤트 발생을 파일 descriptor로 관찰하게 하려면 카운터를 갱신하고 대기 중인 poll 사용자를 깨워야 합니다. 그런데 깨움 callback이 다시 같은 신호 경로로 들어오면 잠금 재획득이나 스택 재귀 문제가 생길 수 있습니다.
 * eventfd_signal_mask는 current->in_eventfd가 이미 설정돼 있으면 경고하고 바로 반환합니다. 아니면 대기 큐 잠금을 IRQ 저장과 함께 잡고 in_eventfd=1로 표시합니다. count가 ULLONG_MAX보다 작을 때만 1을 증가시키며, 대기자가 있으면 EPOLLIN | mask로 wake_up_locked_poll을 호출합니다. 마지막에 in_eventfd=0으로 되돌리고 잠금 및 IRQ 상태를 복원합니다. 포화 상태라도 대기자 깨움 조건은 별도로 검사합니다.
 * count=4이면 5, count=ULLONG_MAX이면 그대로입니다. 두 경우 모두 대기자가 있으면 깨움 호출에 도달할 수 있습니다. 호출자는 재귀 가능성이 있는 custom wakeup 경로라면 eventfd_signal_allowed를 확인하고 허용되지 않을 때 안전한 문맥으로 신호를 미뤄야 한다는 원문 계약을 읽으세요.
 */
void eventfd_signal_mask(struct eventfd_ctx *ctx, __poll_t mask)
{
	unsigned long flags;

	/*
	 * Deadlock or stack overflow issues can happen if we recurse here
	 * through waitqueue wakeup handlers. If the caller users potentially
	 * nested waitqueues with custom wakeup handlers, then it should
	 * check eventfd_signal_allowed() before calling this function. If
	 * it returns false, the eventfd_signal() call should be deferred to a
	 * safe context.
	 */
	if (WARN_ON_ONCE(current->in_eventfd))
		return;

	spin_lock_irqsave(&ctx->wqh.lock, flags);
	current->in_eventfd = 1;
	if (ctx->count < ULLONG_MAX)
		ctx->count++;
	if (waitqueue_active(&ctx->wqh))
		wake_up_locked_poll(&ctx->wqh, EPOLLIN | mask);
	current->in_eventfd = 0;
	spin_unlock_irqrestore(&ctx->wqh.lock, flags);
}
EXPORT_SYMBOL_GPL(eventfd_signal_mask);

/* 학습 해설
 * x86-64 시스템 호출 번호: 범위 검사와 추측 실행 인덱스
 * 사용자 프로그램이 전달한 시스템 호출 번호를 검사 없이 처리기 선택에 쓰면 존재하지 않는 번호로 접근할 수 있습니다. CPU의 추측 실행까지 고려하면 정상 실행의 if 조건과 인덱스 제한을 함께 읽어야 합니다.
 * do_syscall_x64는 int nr를 unsigned int unr로 바꿉니다. 음수는 큰 양수가 되어 NR_syscalls 범위 비교에서 제외됩니다. 범위 안이면 array_index_nospec을 적용한 번호로 x64_sys_call을 호출하고 결과를 regs->ax에 저장한 뒤 true입니다. 범위 밖이면 false이며 여기서는 regs->ax를 새 오류로 쓰지 않습니다. 상위 do_syscall_64가 x64, x32 ABI를 순서대로 시도하고 둘 다 처리하지 못한 번호의 대체 경로를 담당합니다.
 * 설명용 NR_syscalls=500, 32비트 unsigned int를 가정하면 nr=-1은 4294967295라 범위 밖이고 nr=7은 범위 안입니다. 이 helper의 true는 시스템 호출 본문이 성공했다는 뜻이 아니라 번호를 받아 dispatch했다는 뜻입니다. 실제 처리 결과는 regs->ax에 있으며 음수 오류일 수도 있습니다.
 */
static __always_inline bool do_syscall_x64(struct pt_regs *regs, int nr)
{
	/*
	 * Convert negative numbers to very high and thus out of range
	 * numbers for comparisons.
	 */
	unsigned int unr = nr;

	if (likely(unr < NR_syscalls)) {
		unr = array_index_nospec(unr, NR_syscalls);
		regs->ax = x64_sys_call(regs, unr);
		return true;
	}
	return false;
}

static __always_inline bool do_syscall_x32(struct pt_regs *regs, int nr)
{
	/*
	 * Adjust the starting offset of the table, and convert numbers
	 * < __X32_SYSCALL_BIT to very high and thus out of range
	 * numbers for comparisons.
	 */
	unsigned int xnr = nr - __X32_SYSCALL_BIT;

	if (IS_ENABLED(CONFIG_X86_X32_ABI) && likely(xnr < X32_NR_syscalls)) {

/* 학습 해설
 * x86-64 복귀 방식: 시스템 호출 결과와 SYSRET 선택값
 * 커널에서 사용자 공간으로 돌아갈 때 빠른 복귀 명령이 모든 레지스터 상태를 복원할 수 있는 것은 아닙니다. 지원하지 않는 상태로 빠른 복귀를 쓰면 커널 문맥에서 예외가 생길 수 있어 조건에 따라 더 일반적인 복귀 경로를 골라야 합니다.
 * do_syscall_64는 스택 오프셋 적용과 사용자 모드 진입 처리를 거쳐 처리기 dispatch를 instrumentation 구간에 넣습니다. x64와 x32 모두 미처리이고 nr!=-1이면 미구현 호출 helper로 ax를 채웁니다. instrumentation을 끝내고 syscall_exit_to_user_mode를 수행합니다. 이후 Xen PV면 false, RCX와 RIP 또는 R11과 flags가 다르면 false, CS/SS가 사용자 selector와 다르면 false입니다. IP가 TASK_SIZE_MAX 이상이거나 RF/TF 플래그가 있으면 false이며 모든 조건을 통과해야 true입니다.
 * ax에 -EACCES가 저장됐어도 복귀 레지스터 조건이 맞으면 bool 반환은 true일 수 있습니다. 반대로 작업이 성공해 ax=0이어도 TF가 설정되어 있으면 false입니다. bool true는 SYSRET, false는 IRET 복귀 선택이며 사용자에게 돌려주는 syscall 결과값과 다른 반환 통로입니다.
 */
__visible noinstr bool do_syscall_64(struct pt_regs *regs, int nr)
{
	add_random_kstack_offset();
	nr = syscall_enter_from_user_mode(regs, nr);

	instrumentation_begin();

	if (!do_syscall_x64(regs, nr) && !do_syscall_x32(regs, nr) && nr != -1) {
		/* Invalid system call, but still a system call. */
		regs->ax = __x64_sys_ni_syscall(regs);
	}

	instrumentation_end();
	syscall_exit_to_user_mode(regs);

	/*
	 * Check that the register state is valid for using SYSRET to exit
	 * to userspace.  Otherwise use the slower but fully capable IRET
	 * exit path.
	 */

	/* XEN PV guests always use the IRET path */
	if (cpu_feature_enabled(X86_FEATURE_XENPV))
		return false;

	/* SYSRET requires RCX == RIP and R11 == EFLAGS */

/* 학습 해설
 * arm64 시스템 호출: 테이블 선택과 x0 결과 기록
 * 시스템 호출은 CPU가 사용자 레지스터로 전달한 번호를 커널 처리기로 연결하는 경계입니다. 같은 커널이라도 ABI에 따라 호출 테이블과 레지스터 규약이 다르므로 저장된 문맥을 통해 인자와 결과를 주고받습니다.
 * invoke_syscall은 무작위 커널 스택 오프셋을 적용하고 scno<sc_nr이면 array_index_nospec으로 번호를 제한해 전달받은 테이블에서 함수 포인터를 고릅니다. __invoke_syscall은 그 함수를 regs 인자로 부릅니다. 범위 밖이면 do_ni_syscall입니다. 이 helper는 compat 태스크의 별도 호출 처리를 먼저 시도해 -ENOSYS가 아닌 결과면 보존하고 아니면 sys_ni_syscall로 갑니다. 결과는 syscall_set_return_value(current,regs,0,ret)로 x0 위치에 저장합니다. 마지막에 다음에 사용할 스택 오프셋을 고릅니다.
 * sc_nr=100이라는 설명용 테이블에서 scno=99는 마지막 범위 안, 100은 범위 밖입니다. native 진입 do_el0_svc는 x8의 번호와 native 테이블, compat 진입은 x7과 compat 테이블을 공통 경로에 전달합니다. syscall_set_return_value는 compat thread라면 결과의 낮은 32비트로 조정해 regs[0]에 저장합니다.
 */
static void invoke_syscall(struct pt_regs *regs, unsigned int scno,
			   unsigned int sc_nr,
			   const syscall_fn_t syscall_table[])
{
	long ret;

	add_random_kstack_offset();

	if (scno < sc_nr) {
		syscall_fn_t syscall_fn;
		syscall_fn = syscall_table[array_index_nospec(scno, sc_nr)];
		ret = __invoke_syscall(regs, syscall_fn);
	} else {
		ret = do_ni_syscall(regs, scno);
	}

	syscall_set_return_value(current, regs, 0, ret);

	/*
	 * This value will get limited by KSTACK_OFFSET_MAX(), which is 10
	 * bits. The actual entropy will be further reduced by the compiler
	 * when applying stack alignment constraints: the AAPCS mandates a
	 * 16-byte aligned SP at function boundaries, which will remove the
	 * 4 low bits from any entropy chosen here.
	 *
	 * The resulting 6 bits of entropy is seen in SP[9:4].
	 */

/* 학습 해설
 * RISC-V ECALL: 재개 주소·원래 인자·호출 결과의 분리
 * 사용자 프로그램의 시스템 호출에서 돌아올 때 같은 ECALL 명령을 다시 실행하면 반복 호출이 됩니다. 동시에 첫 인자 레지스터는 반환값으로 덮어쓰므로 원래 인자를 따로 보관할 필요가 있습니다.
 * do_trap_ecall_u는 user_mode이면 a7에서 호출 번호를 읽고 epc를 4 증가시키며 orig_a0에 기존 a0를 저장하고 a0에는 기본 -ENOSYS를 둡니다. vector 상태 처리 후 syscall_enter_from_user_mode의 번호를 받아 스택 오프셋을 적용합니다. 번호가 0 이상 NR_syscalls 미만이면 syscall_handler를 부릅니다. handler는 compat 여부에 맞는 테이블에서 함수를 골라 결과를 a0에 저장합니다. 다음 스택 오프셋을 고르고 syscall_exit_to_user_mode로 이어집니다.
 * ECALL 주소 epc=0x1000, 원래 a0=42면 이 경로는 epc=0x1004, orig_a0=42를 준비합니다. 정상 처리 결과가 7이면 a0=7이며 원래 인자 42와 별도로 유지됩니다. 범위 밖이면 이 dispatch는 실행되지 않습니다. 진입 hook이 결과를 바꿀 수 있어 기본 -ENOSYS가 모든 추적 경우에 무조건 마지막 값이라고 단정하지 않습니다.
 */
void do_trap_ecall_u(struct pt_regs *regs)
{
	if (user_mode(regs)) {
		long syscall = regs->a7;

		regs->epc += 4;
		regs->orig_a0 = regs->a0;
		regs->a0 = -ENOSYS;

		riscv_v_vstate_discard(regs);

		syscall = syscall_enter_from_user_mode(regs, syscall);

		add_random_kstack_offset();

		if (syscall >= 0 && syscall < NR_syscalls)
			syscall_handler(regs, syscall);

		/*
		 * Ultimately, this value will get limited by KSTACK_OFFSET_MAX(),
		 * so the maximum stack offset is 1k bytes (10 bits).
		 *
		 * The actual entropy will be further reduced by the compiler when
		 * applying stack alignment constraints: 16-byte (i.e. 4-bit) aligned
		 * for RV32I or RV64I.
		 *
		 * The resulting 6 bits of entropy is seen in SP[9:4].
		 */

/* 학습 해설
 * 블록 요청 시작: 타임아웃·태그·처리 중 상태
 * 장치 드라이버가 요청을 처리하기 시작하면 블록 계층도 언제 시작됐고 언제까지 응답을 기다릴지 알아야 합니다. 명령을 장치에 전달하는 동작과 커널의 요청 상태·시간 추적을 시작하는 동작을 함께 연결하되 서로 구별해야 합니다.
 * blk_mq_start_request는 issue 추적을 기록합니다. 큐 통계가 켜져 있고 passthrough 요청이 아니면 시작 시간·섹터 수·RQF_STATS를 저장하고 QoS issue hook을 호출합니다. 기존 상태가 IDLE이 아니면 경고하고, 타이머를 추가한 뒤 상태를 IN_FLIGHT로 쓰고 tag 위치에 rq를 연결합니다. 무결성 데이터가 있는 쓰기는 blk_integrity_prepare를 호출합니다. bio가 있고 polled 요청이면 bio cookie에 하드웨어 큐 번호를 기록합니다.
 * tag=7인 요청이 시작될 때 rqs[7]이 그 요청을 가리키고 상태가 IN_FLIGHT가 되는 그림을 그리세요. 이 함수 본문에는 NVMe doorbell이나 SCSI queuecommand 호출이 없습니다. 장치별 제출 코드가 이 공통 준비와 실제 명령 전달을 어떻게 배치하는지 이어서 읽어야 합니다.
 */
void blk_mq_start_request(struct request *rq)
{
	struct request_queue *q = rq->q;

	trace_block_rq_issue(rq);

	if (test_bit(QUEUE_FLAG_STATS, &q->queue_flags) &&
	    !blk_rq_is_passthrough(rq)) {
		rq->io_start_time_ns = blk_time_get_ns();
		rq->stats_sectors = blk_rq_sectors(rq);
		rq->rq_flags |= RQF_STATS;
		rq_qos_issue(q, rq);
	}

	WARN_ON_ONCE(blk_mq_rq_state(rq) != MQ_RQ_IDLE);

	blk_add_timer(rq);
	WRITE_ONCE(rq->state, MQ_RQ_IN_FLIGHT);
	rq->mq_hctx->tags->rqs[rq->tag] = rq;

	if (blk_integrity_rq(rq) && req_op(rq) == REQ_OP_WRITE)
		blk_integrity_prepare(rq);

	if (rq->bio && rq->bio->bi_opf & REQ_POLLED)
	        WRITE_ONCE(rq->bio->bi_cookie, rq->mq_hctx->queue_num);
}
